# Generated by build.py from recipe.yml for recipe telnet-hold-a-line-session. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', 'telnet://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -T session.txt telnet://127.0.0.1:8080/ } finally { Stop-Process $server0 }
